import{_ as i,l as r,o as e,c as s,v as t,p as n,x as o,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"光瞳测量","description":"","frontmatter":{"title":"光瞳测量","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pupil-metrology.md","filePath":"litho/pupil-metrology.md","lastUpdated":1789023840000}'),_={name:"litho/pupil-metrology.md"};function m(u,a,c,E,f,A){const l=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="光瞳测量" tabindex="-1">光瞳测量 <a class="header-anchor" href="#光瞳测量" aria-label="Permalink to &quot;光瞳测量&quot;">​</a></h1><div class="epigraph"><p>配方写的环形 σ 是意图；光瞳计看到的才是进入物镜的角谱。SMO 没有计量就是开环。</p><footer>—— 对照源计量 / pupil metrology；[FlexRay](/litho/flexray-pupil)、[SMO](/litho/smo)</footer></div><p><a href="/litho/illumination-uniformity-slit">上一课</a>测场均匀。缺口是角向：部分相干与离轴照明活在光瞳。本课钉光瞳测量，不重推 Hopkins TCC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可编程光瞳会漂：镜子、积尘、通道失效。无计量时，偶极张角和 σ 外环只存在于配方文件。OPE 与 SRAF 对光瞳形状敏感，漂移表现为系统 CD 偏差，被误判成 OPC 模型过期。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在照明光瞳共轭面用阵列传感器或扫描针孔重建 \\(I(\\rho,\\phi)\\)。指标：σ、环宽、偶极平衡、椭圆度、与目标图的 RMSE。进 SMO 闭环：测到的源才是计算光刻用的源，而不是 CAD 里的理想源。</p>',7)),(e(),n(h,null,{default:o(()=>[d(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22%E9%85%8D%E6%96%B9%E5%85%89%E7%9E%B3%22%5D%20--%3E%20ILL%5B%22%E7%85%A7%E6%98%8E%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20ILL%20--%3E%20MEAS%5B%22%E5%85%89%E7%9E%B3%E8%AE%A1%22%5D%0A%20%20MEAS%20--%3E%20SMO%5B%22OPC%20%2F%20SMO%20%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">掩模 3D 与物镜 NA 限制哪些角能进胶。光瞳计应报「离开照明」还是「到达晶圆」——两者差一层物镜与偏振。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TCC 由源与光瞳共同决定。源计量误差线性进部分相干核。场均匀计量不替代光瞳计量。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课剂量传感：标量能量闭环，不是角谱。两者都要，不能互相替代。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光瞳计把照明从开环配方变成可校准角谱。</li><li>SMO / OPE 必须吃实测源。</li><li>出处：源计量通识；SMO 与 FlexRay 课。</li></ul>',7))])}const P=i(_,[["render",m]]);export{T as __pageData,P as default};
